import os
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from zoneinfo import ZoneInfo

SCHEMA_PATH = Path(__file__).with_name("schema.sql")
DEFAULT_DB = Path(__file__).resolve().parent.parent / "data" / "app.db"


def db_path() -> str:
    return os.environ.get("CERT_DB_PATH", str(DEFAULT_DB))


def connect() -> sqlite3.Connection:
    # isolation_level=None: we control transactions explicitly (BEGIN IMMEDIATE for writes).
    # check_same_thread=False: streaming responses may iterate on different threadpool workers.
    conn = sqlite3.connect(db_path(), isolation_level=None, check_same_thread=False, timeout=30)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    conn.execute("PRAGMA foreign_keys=ON")
    conn.execute("PRAGMA busy_timeout=30000")
    return conn


@contextmanager
def write_tx(conn: sqlite3.Connection):
    """Serialize writers: BEGIN IMMEDIATE takes the write lock up front."""
    conn.execute("BEGIN IMMEDIATE")
    try:
        yield conn
        conn.execute("COMMIT")
    except BaseException:
        conn.execute("ROLLBACK")
        raise


def init_schema(conn: sqlite3.Connection) -> None:
    conn.executescript(SCHEMA_PATH.read_text())


def utc_now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def parse_utc(iso: str) -> datetime:
    return datetime.strptime(iso, "%Y-%m-%dT%H:%M:%SZ").replace(tzinfo=timezone.utc)


def local_date(iso_utc: str, tz: str) -> str:
    return parse_utc(iso_utc).astimezone(ZoneInfo(tz)).strftime("%Y-%m-%d")


def local_datetime(iso_utc: str, tz: str) -> str:
    return parse_utc(iso_utc).astimezone(ZoneInfo(tz)).strftime("%Y-%m-%d %H:%M")

"""Quick-start demo data. Idempotent: does nothing if tenants already exist (use --reset to rebuild)."""
import os
import sys

from .db import connect, db_path, init_schema, local_date, write_tx

A5_TS = "2026-01-10T13:30:00Z"

TENANTS = [
    ("East", "Australia/Sydney", "E"),
    ("West", "Australia/Perth", "W"),
]
ADMINS = {
    "alice@east.test": ["East"],
    "bob@west.test": ["West"],
    "carol@multi.test": ["East", "West"],  # many-to-many demo
}
# (learner, enrollment status, already certified at)
SAFETY_ENROLLMENTS = [
    ("Alex Lee", "COMPLETED", A5_TS),          # already certified (A4 duplicate, A5 date)
    ("Sam Park", "COMPLETED", None),            # eligible
    ("Taylor Wong", "COMPLETED", None),         # eligible
    ("Jordan Kim", "INCOMPLETE", None),         # skipped: incomplete
]


def seed(conn) -> bool:
    init_schema(conn)
    if conn.execute("SELECT 1 FROM tenants LIMIT 1").fetchone():
        return False
    with write_tx(conn):
        tenant_ids = {}
        for name, tz, prefix in TENANTS:
            tenant_ids[name] = conn.execute(
                "INSERT INTO tenants(name, timezone) VALUES (?, ?)", (name, tz)
            ).lastrowid
        admin_ids = {}
        for email, tenants in ADMINS.items():
            admin_ids[email] = conn.execute("INSERT INTO admins(email) VALUES (?)", (email,)).lastrowid
            for t in tenants:
                conn.execute(
                    "INSERT INTO admin_tenants(admin_id, tenant_id) VALUES (?, ?)",
                    (admin_ids[email], tenant_ids[t]),
                )
        primary_admin = {"East": admin_ids["alice@east.test"], "West": admin_ids["bob@west.test"]}

        for name, tz, prefix in TENANTS:
            tid = tenant_ids[name]
            safety = conn.execute(
                "INSERT INTO courses(tenant_id, title) VALUES (?, 'Safety 101')", (tid,)
            ).lastrowid
            conn.execute("INSERT INTO courses(tenant_id, title) VALUES (?, 'First Aid 201')", (tid,))
            for i, (learner, status, cert_ts) in enumerate(SAFETY_ENROLLMENTS, start=1):
                lid = conn.execute(
                    "INSERT INTO learners(tenant_id, name) VALUES (?, ?)", (tid, learner)
                ).lastrowid
                conn.execute(
                    "INSERT INTO enrollments(tenant_id, learner_id, course_id, status, completed_at)"
                    " VALUES (?, ?, ?, ?, ?)",
                    (tid, lid, safety, status, "2026-01-05T00:00:00Z" if status == "COMPLETED" else None),
                )
                if cert_ts:
                    cid = conn.execute(
                        "INSERT INTO certificates(tenant_id, learner_id, course_id, serial, learner_name,"
                        " course_title, issued_at, issued_local_date, status)"
                        " VALUES (?, ?, ?, ?, ?, 'Safety 101', ?, ?, 'ACTIVE')",
                        (tid, lid, safety, f"{prefix}-SEED-{i:04d}", learner, cert_ts, local_date(cert_ts, tz)),
                    ).lastrowid
                    conn.execute(
                        "INSERT INTO audit_events(tenant_id, actor_id, action, certificate_id, created_at)"
                        " VALUES (?, ?, 'ISSUE', ?, ?)",
                        (tid, primary_admin[name], cid, cert_ts),
                    )
    return True


def main():
    if "--reset" in sys.argv:
        for suffix in ("", "-wal", "-shm"):
            if os.path.exists(db_path() + suffix):
                os.remove(db_path() + suffix)
    os.makedirs(os.path.dirname(db_path()), exist_ok=True)
    conn = connect()
    print("seeded" if seed(conn) else "already seeded", db_path())


if __name__ == "__main__":
    main()

from dataclasses import dataclass
from typing import Iterator, Optional

import sqlite3
from fastapi import Depends, Header, HTTPException

from .db import connect


def get_conn() -> Iterator[sqlite3.Connection]:
    conn = connect()
    try:
        yield conn
    finally:
        conn.close()


@dataclass(frozen=True)
class Actor:
    id: int
    email: str


@dataclass(frozen=True)
class TenantCtx:
    actor: Actor
    tenant_id: int
    timezone: str


def get_actor(
    x_actor: Optional[str] = Header(default=None),
    conn: sqlite3.Connection = Depends(get_conn),
) -> Actor:
    if not x_actor:
        raise HTTPException(401, "missing X-Actor header")
    row = conn.execute("SELECT id, email FROM admins WHERE email = ?", (x_actor.strip().lower(),)).fetchone()
    if not row:
        raise HTTPException(401, "unknown actor")
    return Actor(row["id"], row["email"])


def get_tenant_ctx(
    actor: Actor = Depends(get_actor),
    x_tenant_id: Optional[str] = Header(default=None),
    conn: sqlite3.Connection = Depends(get_conn),
) -> TenantCtx:
    """Membership is verified against admin_tenants on every request. Non-member -> 404 (non-revealing)."""
    if not x_tenant_id or not x_tenant_id.isdigit():
        raise HTTPException(400, "missing or invalid X-Tenant-Id header")
    row = conn.execute(
        "SELECT t.id, t.timezone FROM tenants t"
        " JOIN admin_tenants at ON at.tenant_id = t.id"
        " WHERE t.id = ? AND at.admin_id = ?",
        (int(x_tenant_id), actor.id),
    ).fetchone()
    if not row:
        raise HTTPException(404, "tenant not found")
    return TenantCtx(actor, row["id"], row["timezone"])

