        except httpx.HTTPError:
            time.sleep(0.1)
    else:
        proc.kill()
        raise RuntimeError("server did not start")
    e = Env(base, db)
    e.proc_env = proc_env
    yield e
    proc.terminate()
    proc.wait(10)

