// ---------------- courses ----------------

function CourseList({
  ctx,
  tenant,
  refresh,
  onOpen,
}: {
  ctx: Ctx;
  tenant: Tenant;
  refresh: number;
  onOpen: (id: number) => void;
}) {
  const [courses, setCourses] = useState<Course[] | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [retry, setRetry] = useState(0);

  useEffect(() => {
    let stale = false;
    setError(null);
    api
      .courses(ctx)
      .then((c) => !stale && setCourses(c))
      .catch((e) => !stale && setError(errText(e)));
    return () => {
      stale = true;
    };
  }, [ctx, refresh, retry]);

  return (
    <section className="card">
      <h2>Courses — {tenant.name}</h2>
      {error ? (
        <div className="banner error">
          Failed to load courses — {error} <button onClick={() => setRetry((n) => n + 1)}>Retry</button>
        </div>
      ) : !courses ? (
        <p className="muted">Loading…</p>
      ) : courses.length === 0 ? (
        <p className="empty">No courses in this tenant.</p>
      ) : (
        <table>
          <thead>
            <tr>
              <th>Course</th>
              <th>Enrolled</th>
              <th>Completed</th>
              <th>Incomplete</th>
              <th>Certified</th>
              <th>Eligible to issue</th>
            </tr>
          </thead>
          <tbody>
            {courses.map((c) => (
              <tr key={c.id} className="clickable" onClick={() => onOpen(c.id)}>
